/* NQC OWNED laboratory: length-prefixed one-byte payload. Not a real target. */
#include <stdio.h>
#include <stdlib.h>

static int parse(const unsigned char *data, size_t size) {
    if (size < 1 || size > 2) return 0;
    return (size_t)(data[0] & 1u) == size - 1;
}

int main(int argc, char **argv) {
    if (argc != 2) return 90;
    FILE *input = fopen(argv[1], "rb");
    if (!input) return 91;
    unsigned char data[3] = {0, 0, 0};
    size_t size = fread(data, 1, sizeof(data), input);
    if (ferror(input)) { fclose(input); return 92; }
    fclose(input);
    int accepted = parse(data, size);
    FILE *trace = fopen("observations.jsonl", "ab");
    if (!trace) return 93;
    if (fputs("{\"input_hex\":\"", trace) < 0) return 94;
    for (size_t i = 0; i < size; i++) {
        if (fprintf(trace, "%02x", (unsigned int)data[i]) < 0) return 94;
    }
    if (fprintf(trace, "\",\"accepted\":%s}\n", accepted ? "true" : "false") < 0) return 94;
    if (fclose(trace)) return 94;
    /* Independent format contract: prefix equals the number of payload bytes. */
    int format_valid = size >= 1 && size <= 2 && (size_t)data[0] == size - 1;
    if (accepted && !format_valid) {
        fputs("NQC_OWNED_LENGTH_PREFIX_TRUNCATION\n", stderr);
        abort();
    }
    return 0;
}

